<?php
namespace App\Http\Controllers;
use App\Models\{Appointment,Doctor,MedicalRecord,Prescription,Patient};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ConsultationController extends Controller {
 public function index(){ $records=MedicalRecord::with(['patient','doctor','prescription.items'])->latest('visit_date')->paginate(15);return view('records.index',compact('records'));}
 public function create(Request $r){$appointment=$r->filled('appointment')?Appointment::with('patient')->findOrFail($r->integer('appointment')):null;$selectedPatient=$r->filled('patient')?Patient::findOrFail($r->integer('patient')):null;return view('records.form',['record'=>new MedicalRecord,'doctors'=>Doctor::where('active',true)->get(),'patients'=>Patient::orderBy('name')->get(),'appointment'=>$appointment,'selectedPatient'=>$selectedPatient]);}
 public function store(Request $r){abort_unless($r->user()->hasRole('administrator','doctor'),403);$d=$r->validate(['patient_id'=>'required|exists:patients,id','doctor_id'=>'required|exists:doctors,id','appointment_id'=>'nullable|exists:appointments,id','visit_date'=>'required|date','symptoms'=>'nullable|string|max:5000','history'=>'nullable|string|max:5000','diagnosis'=>'nullable|string|max:5000','treatment_plan'=>'nullable|string|max:5000','follow_up_date'=>'nullable|date|after_or_equal:visit_date','medicines'=>'nullable|array','medicines.*.name'=>'required_with:medicines|string|max:160','medicines.*.dosage'=>'required_with:medicines|string|max:100','medicines.*.frequency'=>'required_with:medicines|string|max:100','medicines.*.duration'=>'required_with:medicines|string|max:100','medicines.*.instructions'=>'nullable|string|max:500']);$record=DB::transaction(function()use($d,$r){$record=MedicalRecord::create(collect($d)->except('medicines')->put('created_by',$r->user()->id)->all());if(!empty($d['medicines'])){$p=Prescription::create(['medical_record_id'=>$record->id,'doctor_id'=>$d['doctor_id']]);foreach($d['medicines'] as $m)$p->items()->create(['medicine_name'=>$m['name'],'dosage'=>$m['dosage'],'frequency'=>$m['frequency'],'duration'=>$m['duration'],'instructions'=>$m['instructions']??null]);}if(!empty($d['appointment_id']))Appointment::whereKey($d['appointment_id'])->update(['status'=>'Completed']);return $record;});return redirect()->route('patients.show',$record->patient_id)->with('success','Consultation recorded.');}
}
